  displaySource: [
    "// Post-order traversal (DFS)",
    "//",
    "// Sinistra → destra → radice. Il nodo si emette solo quando entrambi i figli",
    "// sono già stati trattati: è l'ordine giusto per cancellare un albero, perché",
    "// un padre non viene liberato finché i figli puntano ancora a lui.",
    "#include <cstdio>",
    "#include <string>",
    "#include <vector>",
    "",
    "",
    "struct Node {",
    "    int data;",
    "    Node* left;",
    "    Node* right;",
    "};",
    "",
    "Node* createNode(int value) {",
    "    Node* node = new Node;",
    "    node->data = value;",
    "    node->left = node->right = nullptr;",
    "    return node;",
    "}",
    "",
    "static Node* gRoot = nullptr;   // radice corrente: serve per disegnare sempre l'albero intero",
    "static std::vector<int> output;",
    "static std::vector<Node*> visited;",
    "",
    "static std::string outputText() {",
    "    std::string s;",
    "    for (size_t i = 0; i < output.size(); ++i) s += (i ? \" \" : \"\") + std::to_string(output[i]);",
    "    return \"output: \" + (s.empty() ? \"(vuoto)\" : s);",
    "}",
    "",
    "static trace::TreeMarks marks(Node* current) {",
    "    trace::TreeMarks m;",
    "    for (Node* v : visited) m.set(v, \"visited\");",
    "    m.set(current, \"current\");",
    "    return m;",
    "}",
    "",
    "void postorder(Node* node) {",
    "    if (node == nullptr) {",
    "        return;",
    "    }",
    "",
    "",
    "    postorder(node->left);",
    "",
    "    postorder(node->right);",
    "",
    "    output.push_back(node->data);",
    "    visited.push_back(node);",
    "",
    "}",
    "",
    "static Node* buildBook() {",
    "    Node* root = createNode(8);",
    "    root->left = createNode(3);",
    "    root->right = createNode(10);",
    "    root->left->left = createNode(1);",
    "    root->left->right = createNode(6);",
    "    root->left->right->left = createNode(4);",
    "    root->left->right->right = createNode(7);",
    "    root->right->right = createNode(14);",
    "    root->right->right->left = createNode(13);",
    "    return root;",
    "}",
    "",
    "static Node* buildSmall() {",
    "    Node* root = createNode(5);",
    "    root->left = createNode(3);",
    "    root->right = createNode(8);",
    "    root->left->left = createNode(2);",
    "    root->right->left = createNode(7);",
    "    return root;",
    "}",
    "",
    "static void freeTree(Node* n) {",
    "    if (!n) return;",
    "    freeTree(n->left);",
    "    freeTree(n->right);",
    "    delete n;",
    "}",
    "",
    "static void run(const char* label, Node* root, const char* intro) {",
    "    output.clear();",
    "    visited.clear();",
    "    gRoot = root;",
    "",
    "    postorder(root);",
    "",
    "    freeTree(root);",
    "}",
    "",
    "int main() {",
    "",
    "    trace::resetNodeIds();",
    "    run(\"albero del libro\", buildBook(), \"Albero binario di ricerca. Post-order: sinistra, destra, radice.\");",
    "    trace::resetNodeIds();",
    "    run(\"albero piccolo\", buildSmall(), \"Un albero più piccolo, per seguire la ricorsione senza perdersi.\");",
    "",
    "    return 0;",
    "}"
  ],
